<script setup>
import { computed, onMounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import { AudioLines, LayoutDashboard, Upload, Music2, Video, Pencil, Trash2, Eye, EyeOff, LogOut, Plus, X, LoaderCircle, Search, ExternalLink } from 'lucide-vue-next'
import api, { mediaUrl } from '../services/api'
const router = useRouter()
const items = ref([]), stats = ref({ total: 0, published: 0, drafts: 0 }), loading = ref(true), saving = ref(false), error = ref(''), success = ref(''), search = ref(''), showForm = ref(false), editingId = ref(null)
const blank = () => ({ title: '', artist: '', category: 'Worship', language: 'Kinyarwanda', description: '', status: 'published', allowDownload: true, media: null, cover: null, existingMedia: '', existingCover: '', type: 'audio' })
const form = ref(blank())
const visibleItems = computed(() => items.value.filter(i => `${i.title} ${i.artist}`.toLowerCase().includes(search.value.toLowerCase())))
function logout() { localStorage.removeItem('gospelhub_token'); localStorage.removeItem('gospelhub_admin'); router.push('/admin/login') }
async function load() { loading.value = true; error.value = ''; try { const [list, stat] = await Promise.all([api.get('/songs/admin/all'), api.get('/songs/admin/stats')]); items.value = list.data; stats.value = stat.data } catch (e) { if (e.response?.status === 401) logout(); else error.value = e.response?.data?.message || 'Could not load dashboard data.' } finally { loading.value = false } }
function newItem() { editingId.value = null; form.value = blank(); error.value = ''; success.value = ''; showForm.value = true }
function editItem(item) { editingId.value = item._id; form.value = { ...blank(), ...item, media: null, cover: null, existingMedia: item.mediaUrl, existingCover: item.coverUrl || '' }; error.value = ''; success.value = ''; showForm.value = true }
function chooseFile(event, field) { form.value[field] = event.target.files?.[0] || null }
async function save() { error.value = ''; success.value = ''; if (!form.value.title.trim() || !form.value.artist.trim() || (!editingId.value && !form.value.media)) { error.value = 'Title, artist, and a media file are required.'; return } const body = new FormData(); for (const key of ['title','artist','category','language','description','status']) body.append(key, form.value[key] || ''); body.append('allowDownload', String(form.value.allowDownload)); if (form.value.media) body.append('media', form.value.media); if (form.value.cover) body.append('cover', form.value.cover); saving.value = true; try { if (editingId.value) await api.put(`/songs/${editingId.value}`, body); else await api.post('/songs', body); success.value = editingId.value ? 'Media updated successfully.' : 'Media uploaded successfully.'; showForm.value = false; await load() } catch (e) { error.value = e.response?.data?.message || 'Upload failed. Check your file size and backend logs.' } finally { saving.value = false } }
async function toggleStatus(item) { error.value = ''; try { const body = new FormData(); body.append('status', item.status === 'published' ? 'draft' : 'published'); await api.put(`/songs/${item._id}`, body); await load() } catch (e) { error.value = e.response?.data?.message || 'Could not update publication status.' } }
async function removeItem(item) { if (!confirm(`Delete “${item.title}”? This also removes its uploaded file.`)) return; try { await api.delete(`/songs/${item._id}`); await load() } catch (e) { error.value = e.response?.data?.message || 'Could not delete item.' } }
onMounted(load)
</script>
<template><div class="min-h-screen bg-[#0d0d14] text-slate-100"><aside class="fixed inset-y-0 left-0 hidden w-64 border-r border-white/8 bg-[#11111a] p-5 lg:block"><a href="/" class="flex items-center gap-3 px-2 py-3"><span class="flex h-10 w-10 items-center justify-center rounded-xl bg-violet-500"><AudioLines/></span><span class="text-lg font-black">Gospel<span class="text-violet-400">Hub</span></span></a><p class="mb-3 mt-10 px-3 text-[10px] font-bold uppercase tracking-[.22em] text-slate-600">WORKSPACE</p><div class="flex items-center gap-3 rounded-xl bg-violet-500/10 px-3 py-3 text-sm font-semibold text-violet-200"><LayoutDashboard :size="18"/> Dashboard</div><a href="/" target="_blank" class="mt-2 flex items-center gap-3 rounded-xl px-3 py-3 text-sm text-slate-400 hover:bg-white/5 hover:text-white"><ExternalLink :size="18"/> View public site</a><div class="absolute bottom-5 left-5 right-5"><button @click="logout" class="flex w-full items-center gap-3 rounded-xl px-3 py-3 text-sm text-slate-400 hover:bg-white/5 hover:text-white"><LogOut :size="18"/> Sign out</button></div></aside>
  <main class="lg:pl-64"><header class="sticky top-0 z-20 flex items-center justify-between border-b border-white/8 bg-[#0d0d14]/90 px-5 py-4 backdrop-blur sm:px-8"><div><p class="text-xs text-slate-500">GOSPELHUB / WORKSPACE</p><h1 class="mt-1 text-xl font-black">Content dashboard</h1></div><div class="flex items-center gap-3"><a href="/" target="_blank" class="rounded-xl border border-white/10 px-3 py-2 text-sm text-slate-300 hover:bg-white/5 lg:hidden">View site</a><button @click="logout" class="rounded-xl border border-white/10 p-2.5 text-slate-400 hover:text-white lg:hidden" aria-label="Sign out"><LogOut :size="18"/></button><button @click="newItem" class="flex items-center gap-2 rounded-xl bg-violet-500 px-4 py-2.5 text-sm font-bold hover:bg-violet-400"><Plus :size="17"/><span class="hidden sm:inline">Add media</span><span class="sm:hidden">Add</span></button></div></header>
  <div class="mx-auto max-w-7xl p-5 sm:p-8"><div v-if="error" class="mb-5 rounded-xl border border-red-400/20 bg-red-400/10 p-4 text-sm text-red-200">{{ error }}</div><div v-if="success" class="mb-5 rounded-xl border border-emerald-400/20 bg-emerald-400/10 p-4 text-sm text-emerald-200">{{ success }}</div>
    <div class="grid gap-4 sm:grid-cols-3"><article class="rounded-2xl border border-white/8 bg-white/[.035] p-5"><div class="flex items-center justify-between text-sm text-slate-400">Total media <Music2 :size="18" class="text-violet-300"/></div><p class="mt-3 text-3xl font-black">{{ stats.total }}</p><p class="mt-1 text-xs text-slate-600">All uploads in your library</p></article><article class="rounded-2xl border border-white/8 bg-white/[.035] p-5"><div class="flex items-center justify-between text-sm text-slate-400">Published <Eye :size="18" class="text-emerald-300"/></div><p class="mt-3 text-3xl font-black">{{ stats.published }}</p><p class="mt-1 text-xs text-slate-600">Visible to website visitors</p></article><article class="rounded-2xl border border-white/8 bg-white/[.035] p-5"><div class="flex items-center justify-between text-sm text-slate-400">Drafts <EyeOff :size="18" class="text-amber-300"/></div><p class="mt-3 text-3xl font-black">{{ stats.drafts }}</p><p class="mt-1 text-xs text-slate-600">Only visible in admin</p></article></div>
    <section class="mt-8 overflow-hidden rounded-2xl border border-white/8 bg-white/[.025]"><div class="flex flex-col justify-between gap-4 border-b border-white/8 p-5 sm:flex-row sm:items-center"><div><h2 class="text-lg font-bold">Your library</h2><p class="mt-1 text-sm text-slate-500">Manage uploaded gospel audio and video.</p></div><div class="relative w-full sm:max-w-xs"><Search :size="17" class="absolute left-3.5 top-1/2 -translate-y-1/2 text-slate-500"/><input v-model="search" placeholder="Search media..." class="w-full rounded-xl border border-white/10 bg-black/20 py-2.5 pl-10 pr-3 text-sm outline-none focus:border-violet-400"/></div></div>
      <div v-if="loading" class="p-10 text-center text-sm text-slate-500">Loading your library…</div><div v-else-if="!visibleItems.length" class="p-12 text-center"><div class="mx-auto flex h-14 w-14 items-center justify-center rounded-2xl bg-violet-500/10 text-violet-300"><Upload/></div><h3 class="mt-4 font-bold">No media yet</h3><p class="mt-2 text-sm text-slate-500">Upload your first gospel song or music video.</p><button @click="newItem" class="mt-5 rounded-xl bg-violet-500 px-4 py-2.5 text-sm font-bold">Upload media</button></div>
      <div v-else class="overflow-x-auto"><table class="w-full min-w-[720px] text-left text-sm"><thead class="bg-white/[.025] text-xs uppercase tracking-wider text-slate-500"><tr><th class="px-5 py-3 font-semibold">Title / artist</th><th class="px-4 py-3 font-semibold">Type</th><th class="px-4 py-3 font-semibold">Category</th><th class="px-4 py-3 font-semibold">Status</th><th class="px-5 py-3 text-right font-semibold">Actions</th></tr></thead><tbody class="divide-y divide-white/5"><tr v-for="item in visibleItems" :key="item._id" class="hover:bg-white/[.025]"><td class="px-5 py-4"><div class="flex items-center gap-3"><img v-if="item.coverUrl" :src="mediaUrl(item.coverUrl)" class="h-11 w-11 rounded-lg object-cover" :alt="item.title"/><div v-else class="flex h-11 w-11 items-center justify-center rounded-lg bg-violet-500/10 text-violet-300"><Video v-if="item.type==='video'" :size="18"/><Music2 v-else :size="18"/></div><div><p class="max-w-[240px] truncate font-semibold text-slate-100">{{ item.title }}</p><p class="mt-1 text-xs text-slate-500">{{ item.artist }}</p></div></div></td><td class="px-4 py-4"><span class="rounded-full bg-white/5 px-2.5 py-1 text-xs text-slate-300">{{ item.type }}</span></td><td class="px-4 py-4 text-slate-400">{{ item.category }}</td><td class="px-4 py-4"><span class="rounded-full px-2.5 py-1 text-xs font-semibold" :class="item.status==='published' ? 'bg-emerald-400/10 text-emerald-300' : 'bg-amber-400/10 text-amber-200'">{{ item.status }}</span></td><td class="px-5 py-4"><div class="flex justify-end gap-1"><button @click="toggleStatus(item)" class="rounded-lg p-2 text-slate-400 hover:bg-white/10 hover:text-white" :title="item.status==='published' ? 'Unpublish' : 'Publish'"> <Eye v-if="item.status!=='published'" :size="16"/><EyeOff v-else :size="16"/></button><button @click="editItem(item)" class="rounded-lg p-2 text-slate-400 hover:bg-white/10 hover:text-white" title="Edit"><Pencil :size="16"/></button><button @click="removeItem(item)" class="rounded-lg p-2 text-slate-400 hover:bg-red-400/10 hover:text-red-300" title="Delete"><Trash2 :size="16"/></button></div></td></tr></tbody></table></div>
    </section><p class="mt-5 text-xs leading-5 text-slate-600">Development storage: media files are saved on the backend machine. Before production, move files to durable object storage and configure HTTPS and a strong JWT secret.</p>
  </div></main>
  <div v-if="showForm" class="fixed inset-0 z-40 flex items-start justify-center overflow-y-auto bg-black/75 p-3 backdrop-blur-sm sm:items-center sm:p-6" @click.self="showForm=false"><section class="my-4 w-full max-w-2xl rounded-3xl border border-white/10 bg-[#171721] shadow-2xl"><header class="flex items-center justify-between border-b border-white/8 p-5 sm:px-7"><div><p class="text-xs font-bold uppercase tracking-[.2em] text-violet-300">CONTENT MANAGEMENT</p><h2 class="mt-1 text-xl font-black">{{ editingId ? 'Edit media' : 'Upload new media' }}</h2></div><button @click="showForm=false" class="rounded-xl p-2 text-slate-400 hover:bg-white/10" aria-label="Close"><X/></button></header><form class="space-y-5 p-5 sm:p-7" @submit.prevent="save"><div class="grid gap-4 sm:grid-cols-2"><label class="block"><span class="mb-2 block text-sm font-semibold text-slate-300">Title *</span><input v-model="form.title" required maxlength="160" class="w-full rounded-xl border border-white/10 bg-black/20 px-3.5 py-3 outline-none focus:border-violet-400" placeholder="Song or video title"/></label><label class="block"><span class="mb-2 block text-sm font-semibold text-slate-300">Artist *</span><input v-model="form.artist" required maxlength="120" class="w-full rounded-xl border border-white/10 bg-black/20 px-3.5 py-3 outline-none focus:border-violet-400" placeholder="Artist name"/></label><label class="block"><span class="mb-2 block text-sm font-semibold text-slate-300">Category</span><select v-model="form.category" class="w-full rounded-xl border border-white/10 bg-[#11111a] px-3.5 py-3 outline-none focus:border-violet-400"><option>Worship</option><option>Praise</option><option>Traditional</option><option>Choir</option><option>Contemporary</option><option>Gospel</option><option>Live Performance</option></select></label><label class="block"><span class="mb-2 block text-sm font-semibold text-slate-300">Language</span><select v-model="form.language" class="w-full rounded-xl border border-white/10 bg-[#11111a] px-3.5 py-3 outline-none focus:border-violet-400"><option>Kinyarwanda</option><option>English</option><option>Swahili</option><option>French</option><option>Other</option></select></label></div>
  <label class="block"><span class="mb-2 block text-sm font-semibold text-slate-300">Audio or video file {{ editingId ? '(optional to replace)' : '*' }}</span><input type="file" accept=".mp3,.mp4,.m4a,.wav,.ogg,.webm,audio/*,video/mp4,video/webm" :required="!editingId" @change="chooseFile($event,'media')" class="block w-full rounded-xl border border-white/10 bg-black/20 p-3 text-sm text-slate-300 file:mr-4 file:rounded-lg file:border-0 file:bg-violet-500/15 file:px-3 file:py-2 file:text-sm file:font-semibold file:text-violet-200"/><p class="mt-2 text-xs text-slate-500">Accepted: MP3, MP4, M4A, WAV, OGG, WEBM. Large files may take time to upload.</p><p v-if="form.media" class="mt-1 text-xs text-violet-300">Selected: {{ form.media.name }} ({{ (form.media.size/1024/1024).toFixed(1) }} MB)</p><p v-else-if="form.existingMedia" class="mt-1 text-xs text-slate-500">Current file: {{ form.existingMedia }}</p></label>
  <label class="block"><span class="mb-2 block text-sm font-semibold text-slate-300">Cover image (optional)</span><input type="file" accept=".jpg,.jpeg,.png,.webp,image/*" @change="chooseFile($event,'cover')" class="block w-full rounded-xl border border-white/10 bg-black/20 p-3 text-sm text-slate-300 file:mr-4 file:rounded-lg file:border-0 file:bg-violet-500/15 file:px-3 file:py-2 file:text-sm file:font-semibold file:text-violet-200"/><p v-if="form.cover" class="mt-1 text-xs text-violet-300">Selected: {{ form.cover.name }}</p></label>
  <label class="block"><span class="mb-2 block text-sm font-semibold text-slate-300">Description</span><textarea v-model="form.description" rows="3" maxlength="2000" class="w-full resize-y rounded-xl border border-white/10 bg-black/20 px-3.5 py-3 outline-none focus:border-violet-400" placeholder="Share a little about this song or video..."></textarea></label>
  <div class="grid gap-4 sm:grid-cols-2"><label class="block"><span class="mb-2 block text-sm font-semibold text-slate-300">Publication</span><select v-model="form.status" class="w-full rounded-xl border border-white/10 bg-[#11111a] px-3.5 py-3 outline-none focus:border-violet-400"><option value="published">Published — visible publicly</option><option value="draft">Draft — admin only</option></select></label><label class="flex items-center gap-3 self-end rounded-xl border border-white/10 bg-black/10 p-3.5"><input v-model="form.allowDownload" type="checkbox" class="h-4 w-4 accent-violet-500"/><span><span class="block text-sm font-semibold">Allow downloads</span><span class="block text-xs text-slate-500">Visitors can download this file</span></span></label></div>
  <p v-if="error" class="rounded-xl border border-red-400/20 bg-red-400/10 p-3 text-sm text-red-200">{{ error }}</p><div class="flex flex-col-reverse gap-3 pt-1 sm:flex-row sm:justify-end"><button type="button" @click="showForm=false" class="rounded-xl border border-white/10 px-5 py-3 text-sm font-semibold text-slate-300 hover:bg-white/5">Cancel</button><button :disabled="saving" class="flex items-center justify-center gap-2 rounded-xl bg-violet-500 px-5 py-3 text-sm font-bold text-white hover:bg-violet-400 disabled:opacity-60"><LoaderCircle v-if="saving" class="animate-spin" :size="17"/>{{ saving ? 'Saving...' : (editingId ? 'Save changes' : 'Upload media') }}</button></div></form></section></div>
</div></template>